const zlib = require('node:zlib');

function crc32(bytes) {
  let crc = 0xffffffff;
  for (const byte of bytes) {
    crc ^= byte;
    for (let bit = 0; bit < 8; bit += 1) crc = (crc >>> 1) ^ ((crc & 1) ? 0xedb88320 : 0);
  }
  return (crc ^ 0xffffffff) >>> 0;
}

function pngDataUrl(width = 1, height = 1, metadataBytes = 0) {
  function chunk(type, data) {
    const result = Buffer.alloc(data.length + 12);
    result.writeUInt32BE(data.length);
    result.write(type, 4, 4, 'ascii');
    data.copy(result, 8);
    result.writeUInt32BE(crc32(result.subarray(4, -4)), result.length - 4);
    return result;
  }
  const header = Buffer.alloc(13);
  header.writeUInt32BE(width, 0);
  header.writeUInt32BE(height, 4);
  header[8] = 8;
  header[9] = 6;
  const image = Buffer.concat([Buffer.from('89504e470d0a1a0a', 'hex'), chunk('IHDR', header),
    ...(metadataBytes ? [chunk('tEXt', Buffer.concat([Buffer.from('Comment\0'), Buffer.alloc(metadataBytes, 65)]))] : []),
    chunk('IDAT', zlib.deflateSync(Buffer.alloc((1 + width * 4) * height))), chunk('IEND', Buffer.alloc(0))]);
  return 'data:image/png;base64,' + image.toString('base64');
}

// A real 1 x 1 JPEG encoded by System.Drawing, independent of our validator.
const JPEG_DATA_URL = 'data:image/jpeg;base64,';

module.exports = { pngDataUrl, JPEG_DATA_URL };
